using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Looks up a configuration value by key name.")]
    public static string GetConfigValue(
        [Description("The configuration key to look up (e.g. 'MaxRetries', 'Timeout')")] string key)
    {
        var settings = AppConfig.Current;
        return settings.TryGetValue(key, out var value)
            ? $"{key} = {value}"
            : $"Key '{key}' not found. Available keys: {string.Join(", ", settings.Keys)}";
    }

    [McpServerTool, Description("Lists all available configuration keys.")]
    public static string ListConfigKeys()
    {
        return string.Join("\n", AppConfig.Current.Keys.Order());
    }
}

using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(
        UriTemplate = "config://app",
        Name = "App Configuration",
        MimeType = "application/json"),
     Description("Returns the full application configuration as JSON.")]
    public static string GetAppConfig()
    {
        return JsonSerializer.Serialize(AppConfig.Current, AppConfig.JsonOptions);
    }

    [McpServerResource(
        UriTemplate = "config://app/{section}",
        Name = "Configuration Section",
        MimeType = "application/json"),
     Description("Returns a filtered subset of configuration for a given section prefix.")]
    public static string GetConfigSection(string section)
    {
        var filtered = AppConfig.Current
            .Where(kv => kv.Key.StartsWith(section, StringComparison.OrdinalIgnoreCase))
            .ToDictionary(kv => kv.Key, kv => kv.Value);

        return filtered.Count > 0
            ? JsonSerializer.Serialize(filtered, AppConfig.JsonOptions)
            : JsonSerializer.Serialize(new { error = $"No keys found for section '{section}'" });
    }
}

using System.Text.Json;

/// <summary>Sample in-memory configuration store.</summary>
public static class AppConfig
{
    public static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    public static Dictionary<string, string> Current { get; } = new()
    {
        ["App.Name"]        = "HttpMcpServer",
        ["App.Version"]     = "1.0.0",
        ["App.Environment"] = "Development",
        ["Retry.MaxRetries"] = "3",
        ["Retry.DelayMs"]    = "500",
        ["Cache.Enabled"]    = "true",
        ["Cache.TtlSeconds"] = "300",
    };
}

